window.__BUNDLE__={"generatedAt":"2026-10-02T20:12:14.914916+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-25","archiveCutoff":"2021-10-03","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":284,"arxiv":2058,"total":2342},"freshness":{"latestPaperDate":"2026-10-02","latestPublishedDate":"2026-10-02","latestBatchCount":489,"newInLast24h":526,"newInLast48h":1082},"historyTotal":20066,"topicCounts":{"Multi-Agent":2456,"Evaluation":10833,"Planning":1561,"Memory":408,"Code Agent":799,"Interpretability":721,"Agentic RAG":1298,"Agentic Search":1662,"RL for LLM":1162,"Reasoning":5624,"Hallucination":1010,"Post-Training":2344,"Alignment":2689,"World Model":331,"Tool Use":1251,"Agent Safety":2389,"Computer Use":294,"Reflection":717,"VLM Training":1478,"LLM Training":2464,"Fine-tuning":3077,"Multimodal Agent":116,"Agent Framework":819,"Error Attribution":125,"Data Engine":401},"count":36,"recentTotal":3646,"archiveCount":0,"archiveTotal":16420,"sources":{"hf":114,"arxiv":3532,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"hfUrl":"https://huggingface.co/papers/2610.01415","tags":["Evaluation"],"upvotes":67,"pdf":"https://arxiv.org/pdf/2610.01415.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01415","id":"arxiv:2610.01415","topics":["Evaluation"],"title":"Beyond Memory: Harnessing Long-Horizon Agents with Explicit Belief States","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01415","source":"hf","authors":["Yu Luo","Jiamin Jiang","Yimin Zuo","Xidao Wen","Rongchen Gao","Yongqian Sun","Shenglin Zhang","Guiyang Liu","Cheng Zhang","Fang Situ","Qi Zhou","Dan Pei"],"abstract":"Large language model (LLM) agents can now undertake increasingly complex tasks, but the way they organize interaction history into memory does not ensure a coherent understanding of the current world. We introduce PoS, an inference-time framework that constructs and continually maintains explicit belief states as the agent's decision context. Each belief combines an estimate of the current world state with unresolved task requirements, making explicit what the agent still needs to learn and accomplish. To keep this belief reliable and actionable, PoS validates its consistency and monitors task progress to detect Belief Trapping, where the agent continues to act without making meaningful progress toward the goal. Recovery is then tailored to both the trapping pattern and the type of unresolved task requirement. Experiments on four benchmarks spanning execution and diagnosis show that PoS "},{"hfUrl":"https://huggingface.co/papers/2610.02193","tags":["Reasoning","Planning"],"upvotes":57,"pdf":"https://arxiv.org/pdf/2610.02193.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02193","id":"arxiv:2610.02193","topics":["Reasoning","Planning"],"title":"Hierarchical Continuous Diffusion Language Models","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02193","source":"hf","authors":["Hui Ren","Zihan Li","Chang Liu","Huidong Liu","Alexander Schwing"],"abstract":"Discrete diffusion language models offer a compelling alternative to autoregressive generation for tasks demanding bidirectional reasoning and global constraint satisfaction. Yet they share a structural bottleneck: when decoding in parallel, each token is sampled independently from its marginal, severing the statistical dependencies among the tokens decoded together. Continuous diffusion language models avoid this by denoising a shared continuous state, but their denoiser sees only that state, so nothing ties it to a valid token configuration until it is finally decoded. To address this, we propose Hierarchical Continuous Diffusion Language Models (HC-DLM), which couple discrete token generation with a continuous latent trajectory in a single, principled denoising process, whose training objective is derived from a variational bound on the token likelihood. In contrast to recent methods "},{"hfUrl":"https://huggingface.co/papers/2610.02162","tags":["Evaluation","World Model"],"upvotes":56,"pdf":"https://arxiv.org/pdf/2610.02162.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02162","id":"arxiv:2610.02162","topics":["Evaluation","World Model"],"title":"World Observer: Joint Actor-Observer Generation for Persistent World Modeling","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02162","source":"hf","authors":["Hyunwook Choi","Dahyun Chung","Hyunsung Kim","Siyoon Jin","Jinhyeok Choi","Junyoung Seo","Seungryong Kim"],"abstract":"How can a world model continuously observe regions beyond the actor's current view? Video world models simulate how an environment evolves from an agent's actions, yet remain actor-centric. Once an object leaves the actor's view, they lose direct evidence of its evolution, often failing to preserve its state and dynamics upon re-entry. To address this, we introduce World Observer, which decouples observing from acting by jointly generating a perspective actor for the agent-centric view with one or more panoramic observers that watch selected world regions. This allows objects that leave the actor's view to remain visually evolving in an observer, so their updated states are reflected when they re-enter. We ground the actor and observers by warping from a shared panoramic source for explicit geometric correspondence, and introduce an Observer Sink of high-resolution perspective references"},{"hfUrl":"https://huggingface.co/papers/2610.01509","tags":["Post-Training","Tool Use","Evaluation","RL for LLM"],"upvotes":45,"pdf":"https://arxiv.org/pdf/2610.01509.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01509","id":"arxiv:2610.01509","topics":["Post-Training","Tool Use","Evaluation","RL for LLM"],"title":"Sharpening Tax in Post-Training","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01509","source":"hf","authors":["Changdae Oh","Qi Zeng","Qi Qi","Andrey Zhmoginov","Deren Lei","Yun He","Hoang Phan","Hangoo Kang","Azalia Mirhoseini","Sharon Li"],"abstract":"An emerging hypothesis about reinforcement learning (RL) post-training of large language models (LLMs) is that it merely sharpens existing behaviors of a base model, improving single-shot accuracy at the cost of solution coverage. Although this trade-off has been observed in math and coding tasks, it need not extend to agentic tasks, where multi-turn tool use and interaction may require capabilities newly acquired during post-training. Our surprising finding is that pre-trained LLMs, equipped with a light inference harness, can serve as capable agents. Despite far lower accuracy (pass@1), they often surpass their post-trained counterparts in solution coverage (pass@K) given a sufficient test-time budget. We further analyze the underlying mechanism and show that post-training pushes tasks toward two extremes, always solved or never solved, and thereby improves sampling efficiency and cons"},{"hfUrl":"https://huggingface.co/papers/2610.02205","tags":["VLM Training","Evaluation","Alignment","World Model"],"upvotes":34,"pdf":"https://arxiv.org/pdf/2610.02205.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02205","id":"arxiv:2610.02205","topics":["VLM Training","Evaluation","Alignment","World Model"],"title":"ROWBench: Do Video Models Render What the Program Specifies?","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02205","source":"hf","authors":["Zheng-Hui Huang","Guixu Lin","Yu-Ju Tsai","Jian-Kai Zhu","Fengbo Lan","Yu-Lun Liu","Yung-Yu Chuang","Kaipeng Zhang","Zhixiang Wang"],"abstract":"Programmable world models separate executable dynamics from visual generation, offering a promising foundation for next-generation game engines. However, their visual adherence to explicit rules and interactions remains insufficiently evaluated. Existing benchmarks assess visual quality, controllability, and instruction or physical adherence, but rarely test fidelity to fine-grained, program-specified world events. We introduce PROWBench, comprising 170 programmatically constructed episodes and 600 proxy videos covering diverse scenes and interactions. PROWBench logs entity states and timestamped events, including those outside the camera's field of view, as replayable world records, from which it renders synchronized views and proxy representations. This enables generated videos to be checked against the observable consequences of program execution. An extensible framework constructs sc"},{"hfUrl":"https://huggingface.co/papers/2610.01215","tags":["Computer Use","Fine-tuning","World Model"],"upvotes":34,"pdf":"https://arxiv.org/pdf/2610.01215.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01215","id":"arxiv:2610.01215","topics":["Computer Use","Fine-tuning","World Model"],"title":"AutoGUIWorld: Image Generators as Visual World Models for GUI Agent","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01215","source":"hf","authors":["Cheng Yang","Yifan Wu","Yutao Huang","Zhaohua Zhang","Beiduo Chen","Muxi Chen","Chenchen Zhao","Hexuan Deng","Haolin Yang","Geyuan Zhu","Sa Zhu","Jianhuan Zhuo","Qiuyong Xiao","Jianhao Ruan","Yiran Peng","Jiayi Zhang","Tian Ye","Xinlei Yu","Tianwen Jiang","Jihong Zhang","Yuyu Luo"],"abstract":"GUI agents require high-quality interaction trajectories to learn how software environments respond to actions, maintain state, and support multi-step workflows. However, the diversity of available trajectories is constrained by the applications, interface states, and workflows accessible in the underlying environments. Expanding this coverage requires deploying increasingly diverse and complex software, with specialized applications imposing additional installation, configuration, and runtime costs. We introduce AutoGUIWorld, a data generation framework that combines the visual priors of image generators with the task knowledge of a planner to synthesize GUI interaction trajectories without deploying or running the corresponding software environments. AutoGUIWorld samples initial GUI scenes from structured specifications of operating-system context, visual appearance, and interface stat"},{"hfUrl":"https://huggingface.co/papers/2610.00574","tags":["Post-Training","Reasoning","RL for LLM"],"upvotes":32,"pdf":"https://arxiv.org/pdf/2610.00574.pdf","date":"2026-10-02","submittedDate":"2026-09-30","url":"https://arxiv.org/abs/2610.00574","id":"arxiv:2610.00574","topics":["Post-Training","Reasoning","RL for LLM"],"title":"Make Sparse Rewards Count: Density-Aware Reward Aggregation for Multi-Reward RL","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00574","source":"hf","authors":["Tong Zheng","Skylar Zhai","Zhan Cheng","TianMing Sha","Youling Huang","Shuo Zhou","Shaotong Qi","Jingcheng Liang","Xuwei Ding","Pengcheng Xu"],"abstract":"Multi-reward reinforcement learning trains large language models to satisfy multiple behavioral objectives simultaneously. Reward-wise normalization, as used in GDPO, preserves reward-specific relative information within rollout groups, but different objectives can still exhibit uneven learning progress. We study this behavior through advantage energy, the sum of a reward's squared advantages over a batch. Under idealized GDPO normalization, we show that this energy is proportional to active-group density: the fraction of rollout groups in which the reward provides nonzero relative advantages. This reveals a residual batch-level signal imbalance and provides a basis for calibrating reward contributions. Based on this relation, we propose Density-Aware Reward Aggregation (DARA). We derive an inverse-square-root density correction that gives greater weight to signals from less frequently a"},{"hfUrl":"https://huggingface.co/papers/2610.02196","tags":["Planning"],"upvotes":24,"pdf":"https://arxiv.org/pdf/2610.02196.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02196","id":"arxiv:2610.02196","topics":["Planning"],"title":"InterEvolve: Test-Time Evolution of Reward Programs for Humanoid Loco-Manipulation","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02196","source":"hf","authors":["Zhuo Lin","Sirui Xu","Liuyu Bian","Yu-Xiong Wang","Liang-Yan Gui"],"abstract":"We study test-time evolution for humanoid loco-manipulation: solving tasks that a controller was never trained for by repurposing its existing skills, improving from its own attempts, and retaining what it learns, without retraining. Our key insight is that a broad controller already holds much of the competence a new task needs, and that this competence becomes accessible through an interface between planning and control that is expressive enough to specify contact-rich, multi-stage interactions, yet executable and measurable enough that execution feedback can guide planning from experience. InterEvolve realizes this interface with two components. First, we develop an object-aware forward-backward (FB) behavioral foundation model, whose object residuals on a frozen body prior turn a new reward about the body or objects into loco-manipulation behavior at test time. Second, we specify tas"},{"hfUrl":"https://huggingface.co/papers/2610.02122","tags":["Reasoning","Evaluation"],"upvotes":13,"pdf":"https://arxiv.org/pdf/2610.02122.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02122","id":"arxiv:2610.02122","topics":["Reasoning","Evaluation"],"title":"Argo-Bench: Evaluating Data Agents on Enterprise-Scale Workflows","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02122","source":"hf","authors":["Gabriel Tomitsuka","Arman Raayatsanati","Emma Xing","Duke Gand","Joseph J Ma"],"abstract":"Real-world enterprise data science and analytics workflows require reasoning across dozens of tables, performing statistical analyses, and acting on the results. Established text-to-SQL benchmarks evaluate query generation alone, and audits have found their answer keys frequently wrong. Because real enterprise warehouses are too sensitive to release, these benchmarks are built on public datasets where a business event fits in a single table. We introduce Argo-Bench, an evaluation framework comprising 210 data science and analytics tasks. Drawing on public data, peer-reviewed industry literature, and regulatory filings, we simulate a food delivery platform in New York City at true scale, with 81 million orders in 2024, grounded economics, fraud patterns, and marketplace incentives. We export this world to an ERP warehouse of 235 tables and 7.5 billion rows, modeled on the Oracle E-Busines"},{"hfUrl":"https://huggingface.co/papers/2610.00964","tags":["Post-Training"],"upvotes":13,"pdf":"https://arxiv.org/pdf/2610.00964.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.00964","id":"arxiv:2610.00964","topics":["Post-Training"],"title":"RPTune: Learned Context Curation for LLM Catalog Search","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00964","source":"hf","authors":["Chuxuan Hu","Hejie Cui","Norman Huang","Shubham Kumar Bharti","Wang-Chiew Tan","Sercan Ö. Arık"],"abstract":"For small merchant businesses (SMBs) whose catalogs fit within a long-context LLM, full-catalog prompting offers a compelling alternative to multi-stage retrieval designed primarily for large marketplaces with millions of items. However, fitting the full catalog into the context window does not ensure that the model can use it effectively, since LLMs do not exploit long contexts uniformly. We therefore study in-context catalog search through two complementary questions: (1) how to curate and present catalogs to the LLM, and (2) how to adapt the LLM for product selection on curated contexts. We propose RPTune, an end-to-end framework that couples learned catalog curation with LLM post-training using automatically generated, catalog-grounded supervision. An encoder-reorganizer curator orders and prunes products guided by downstream LLM feedback, while the resulting curated catalogs in turn"},{"hfUrl":"https://huggingface.co/papers/2610.00483","tags":["Alignment"],"upvotes":9,"pdf":"https://arxiv.org/pdf/2610.00483.pdf","date":"2026-10-02","submittedDate":"2026-09-30","url":"https://arxiv.org/abs/2610.00483","id":"arxiv:2610.00483","topics":["Alignment"],"title":"PixelDense: Dense Prediction as Representation Alignment for Pixel Diffusion","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00483","source":"hf","authors":["Lehan Yang","Daiqing Qi","Wenhao Zhang","Avery Li","Yiqing Yang","Yifan Li","Yu Kong","Haitian Zheng","Zhifei Zhang","Zhe Lin","Varun Jampani","Sheng Li"],"abstract":"Representation alignment (REPA) accelerates diffusion transformer training, but its alignment targets are almost exclusively semantic encoders such as DINOv2 and CLIP. Recent analysis points to spatial structure, not global semantics, as the carrier of the alignment effect, yet dense-prediction foundation models trained to predict that structure remain overlooked as REPA targets. In pixel-space diffusion, SAM2, Depth Anything v2, and Metric3D v2 each outperform the DINOv2-only GenEval baseline, with the two geometric teachers leading the segmentation teacher. A flat sum of all four teachers, however, lands below the best single geometric teacher, as semantic and geometric gradients compete for one denoiser projection. We introduce PixelDense, which routes DINOv2 and SAM2 through a semantic projection stream, routes Depth Anything v2 and Metric3D v2 through a geometric projection stream, "},{"hfUrl":"https://huggingface.co/papers/2606.10953","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"upvotes":8,"pdf":"https://arxiv.org/pdf/2606.10953.pdf","date":"2026-10-02","url":"https://arxiv.org/abs/2606.10953","id":"arxiv:2606.10953","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"title":"Architect-Ant: Editable Automatic Furnishing of Architectural Floor Plans","arxiv":"https://arxiv.org/abs/2606.10953","source":"hf","authors":["Fedor Rodionov","Aleksandar Cvejic","Michael Birsak","John Femiani","Peter Wonka"],"abstract":"Furnished floor plans support real-estate visualization, interior design, and architectural workflows, yet automatic furnishing remains challenged by limited real-world data and the need to satisfy interacting geometric and functional constraints. We ask whether professional furnishing knowledge can be learned from real floor plans using a pretrained model, enabling direct constraint-aware layout generation without relying on costly iterative agentic inference. We introduce AntPlan, a curated dataset of 505 real professional architectural floor plans with dense furniture annotations spanning 92 object classes and ten residential room categories, and Architect-Ant, a framework for generating furniture layouts. Architect-Ant represents layouts with an editable coordinate-based DSL and first learns professional furnishing patterns through supervised fine-tuning. It is then optimized with GR"},{"hfUrl":"https://huggingface.co/papers/2610.02181","tags":["Tool Use","Reasoning","Evaluation","RL for LLM","Data Engine"],"upvotes":7,"pdf":"https://arxiv.org/pdf/2610.02181.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02181","id":"arxiv:2610.02181","topics":["Tool Use","Reasoning","Evaluation","RL for LLM","Data Engine"],"title":"OmniSeek: Native Tool Integration for Multi-turn Audio-Visual Reasoning","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02181","source":"hf","authors":["Haibo Wang","Jiteng Mu","Jialu Li","Jingru Yi","Yuanjun Xiong","Jianming Zhang","Lifu Huang","Mingze Xu"],"abstract":"We present OmniSeek, an agentic framework that transforms an Omni Large Language Model (Omni-LLM) into an active, multi-turn reasoning agent with native tool use. Rather than passively processing an entire audio-visual sequence in a single forward pass, OmniSeek makes evidence acquisition part of the reasoning process: it dynamically decides whether to look or listen, and over which temporal window, to retrieve sparse but critical evidence across different modalities within long contexts. Through an iterative multi-turn protocol, the retrieved raw audio or visual segments are appended back into the context to support subsequent reasoning. To cold-start this capability, we build a data engine that synthesizes OmniTraj-170K, a corpus of multi-hop Chain-of-Thought trajectories with interleaved audio and visual evidence. We first supervise the model on these trajectories to instill multi-tur"},{"hfUrl":"https://huggingface.co/papers/2610.00825","tags":["LLM Training","Evaluation","Alignment","Fine-tuning"],"upvotes":7,"pdf":"https://arxiv.org/pdf/2610.00825.pdf","date":"2026-10-02","submittedDate":"2026-09-30","url":"https://arxiv.org/abs/2610.00825","id":"arxiv:2610.00825","topics":["LLM Training","Evaluation","Alignment","Fine-tuning"],"title":"Align Then Reason: A Multimodal Lip-Sync Judge for Dubbing","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00825","source":"hf","authors":["Rui Liu","Bhavin Jawade","Haoqi Li","Shivam Mehta","Karan Saxena","Yinghong Lan","Cameron R. Wolfe"],"abstract":"Dubbing quality control requires a reference-free judge that can determine whether a candidate text line matches a speaker's visible articulation in both content and timing, using only silent video and text because dubbed audio may not yet exist. Existing visual speech recognizers and video-language models are poorly suited to this setting: even when fine-tuned to recover spoken content from lip motion, they remain largely insensitive to temporal errors. We introduce $\\textit{Align Then Reason}$ (ATR), a multilingual lip-sync judge that first establishes a monotonic alignment between frame-level lip representations and the phonetic units of the candidate line, then reasons over this alignment to make the final judgment. An alignment scorer provides the LLM with both local evidence for each phonetic unit and a calibrated global alignment score, enabling it to reason jointly about content "},{"hfUrl":"https://huggingface.co/papers/2610.00313","tags":["Code Agent"],"upvotes":4,"pdf":"https://arxiv.org/pdf/2610.00313.pdf","date":"2026-10-02","submittedDate":"2026-09-29","url":"https://arxiv.org/abs/2610.00313","id":"arxiv:2610.00313","topics":["Code Agent"],"title":"Rules to Tools: Executable Checks for LLM Agents in Scientific Computing","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00313","source":"hf","authors":["Jingjie Ning","Guojiang Zhao","Chen Xu","Shanshan Zhong","Xiaochuan Li","Ji Zeng","Guolin Ke"],"abstract":"Scientific coding agents receive equations, boundary conditions, and output requirements in writing, then must assess the programs they revise. Rules to Tools (R2T) supplies prepared executable checks of public scientific requirements. Matched SciCode repair groups share written checks, starting programs, model, and budgets; the tool group receives a callable implementation. Across two task-ID cohorts, complete repair is 26/30 with text and 29/30 with the prepared checks. Three task IDs favor tools, one favors text, and eleven tie. The eight-ID cohort scores 13/16 versus 15/16, with a task-cluster bootstrap 95% interval of [-12.5, 43.75] percentage points for the difference. The larger shared-definition SciCode cohort ties at 13/24 per group. Five development-exposed tasks with alternate starting programs score 3/10 versus 7/10. The tool group favors tasks 17, 77, and 11; initial checks "},{"hfUrl":"https://huggingface.co/papers/2610.00314","tags":["Agentic Search","Evaluation","Alignment"],"upvotes":1,"pdf":"https://arxiv.org/pdf/2610.00314.pdf","date":"2026-10-02","submittedDate":"2026-09-29","url":"https://arxiv.org/abs/2610.00314","id":"arxiv:2610.00314","topics":["Agentic Search","Evaluation","Alignment"],"title":"Predictive Credit: Measuring What Scientific Explanations Add to Experimental Forecasts","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00314","source":"hf","authors":["Jingjie Ning","Xueqi Li","Yibo Kong","Dongting Li"],"abstract":"Research agents explain planned experiments. We measure predictive credit with paired forecasts sharing an intervention, forecaster, and outcome while varying description, matched explanation, and donor context. Five checks track commitment, delivery, predictive gain, alignment, and known-signal uptake. Across 336 prospective states in controlled learning, 12 Tox21 endpoints, and 24 OpenML tasks, v5's frozen credit decision was inconclusive. Tox21's preregistered ROC AUC interval-score harm test was unmet ($D-M=-.0026$, 95 percent interval [$-.0174$, .0104]); OpenML's joint formation, point-equivalence, and repeatability rule was unmet. Matched point-accuracy gains over description remained unconfirmed, and Tox21/OpenML seed-donor intervals spanned zero. Under requested DeepSeek V4 Pro, matched and donor cards reduced secondary Tox21 drift by 64.5 and 59.1 percent. A DeepSeek V4 Flash re"},{"hfUrl":"https://huggingface.co/papers/2610.01017","tags":["Multi-Agent","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.01017.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01017","id":"arxiv:2610.01017","topics":["Multi-Agent","Evaluation"],"title":"Pay for the Fault, Not the Flow: Label-Free In-Flow Multi-Agent Workflow Optimization","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01017","source":"hf","authors":["Xuehang Guo","Haoyu Wang","Shengyu Chen","Zach Chen","Wei Cheng","Qingyun Wang","Haifeng Chen"],"abstract":"Large language models (LLMs) increasingly construct multi-agent workflows that decompose a complex task and assign specialist agents from a pool. However, building such a workflow well remains challenging: how finely to divide the task, which agent to trust with each subtask, and when to create a new specialist are all critical decisions a workflow constructor needs to settle up front. Thus, whether each subtask succeeds remains unknown until the workflow runs. Yet, improving a workflow is costly. Locating a fault usually requires a reference answer, a graded outcome, or a trained assessor, and the fix is applied to the whole workflow through re-execution, re-search, or retraining. We propose InFlowOp, which prices every decision in one label-free cost that weighs how well an agent's competence meets what a subtask demands against how much that agent takes to run. Before execution, InFlo"},{"hfUrl":"https://huggingface.co/papers/2610.01026","tags":["Multi-Agent"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.01026.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01026","id":"arxiv:2610.01026","topics":["Multi-Agent"],"title":"It Takes Workflows to Evolve Better Workflows","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01026","source":"hf","authors":["Xuehang Guo","Haoyu Wang","Haifeng Chen","Yangyi Chen","Zhenhailong Wang","Qingyun Wang"],"abstract":"Tackling complex real-world tasks can exceed the capabilities of a single large language model (LLM), motivating the use of multi-agent workflows that coordinate specialized agents to work together on these tasks. Recent methods train LLMs to construct better workflows from execution outcomes, but they optimize only the workflow generator, while the other agents that build or execute each workflow remain fixed even though every outcome depends on all of them. However, extending training beyond the generator is challenging: the agents are coupled, and a workflow's outcome is a single sparse score that cannot tell which agent causes a failure. We propose FloWright, which leverages the workflow as a harness to optimize workflows. By introducing a hierarchical, structure-aware reward paradigm, FloWright enables one role to self-evolve and two or more roles to co-evolve, with no additional mo"},{"hfUrl":"https://huggingface.co/papers/2610.01939","tags":["VLM Training","Planning"],"upvotes":19,"pdf":"https://arxiv.org/pdf/2610.01939.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01939","id":"arxiv:2610.01939","topics":["VLM Training","Planning"],"title":"Fewer Tokens, Better Action: GPT-6 Astra Robot Agents with 14% Higher Success Rate but 65% Fewer Tokens","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01939","source":"arxiv","authors":["Ruiyang Si","Jianxin Bi","Shunyu Yang","Rui Ni","Wenbo Huang","Qiang Wang","Shulong Jiang","Duomin Wang","Xiuyu Li","Haiwen Feng","Zhen Dong","Daquan Zhou"],"abstract":"Vision language model (VLM) agents can control robots through visual feedback and action primitives, but repeated model invocations and redundant observations incur substantial token overhead. We introduce PyRUA-Lean, an interactive code-execution framework that couples feedback-driven primitive composition with selective observation: the agent composes classical robot primitives and learned vision-language-action (VLA) policies into Python cells that perform conditional checks and local retries, returning only explicitly requested images and state feedback for replanning. Across 700 simulated task instances from LIBERO-PRO, RoboTwin 2.0, and RoboCasa365, we compare PyRUA-Lean with a tool-calling baseline using the same GPT-6 Astra planner and underlying robot primitives. Under equal LLM-call budgets, PyRUA-Lean increases overall success from 63.1% to 71.7%. On instances solved by both a"},{"hfUrl":"https://huggingface.co/papers/2610.00559","tags":["VLM Training","Reasoning","Evaluation"],"upvotes":11,"pdf":"https://arxiv.org/pdf/2610.00559.pdf","date":"2026-10-02","submittedDate":"2026-09-30","url":"https://arxiv.org/abs/2610.00559","id":"arxiv:2610.00559","topics":["VLM Training","Reasoning","Evaluation"],"title":"PhysVista: Benchmarking Physical Intelligence in VLMs via a Perception-Reasoning-Assessment Loop","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00559","source":"arxiv","authors":["Xinge Peng","Yiting Lu","Tianwu Zhi","Wen Wen","Jianzhao Liu","Xin Li","Zhibo Chen"],"abstract":"Vision-Language Models (VLMs) have shown strong multimodal reasoning capabilities, yet whether they truly capture the physical consistency underlying real-world dynamics remains unclear. Existing benchmark paradigms often suffer from fragmented evaluation, focusing on isolated cognitive stages while overlooking the inherent synergy between perception, reasoning, and physical judgment. The lack of a holistic perspective limits the ability to diagnose whether VLMs can reliably evaluate the physical authenticity of emerging generative models. To address these issues, we introduce PhysVista, a benchmark designed to evaluate physical intelligence in VLMs through a closed cognitive loop framework inspired by the human seeing-reasoning-assessment process. PhysVista restores this loop by jointly evaluating physical state perception, physical dynamics reasoning, and physical plausibility assessme"},{"hfUrl":"https://huggingface.co/papers/2610.02148","tags":["VLM Training","Alignment","Fine-tuning"],"upvotes":9,"pdf":"https://arxiv.org/pdf/2610.02148.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02148","id":"arxiv:2610.02148","topics":["VLM Training","Alignment","Fine-tuning"],"title":"Omni-Embed-Mini: Binding Modalities Without Forgetting via Dense Distillation","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02148","source":"arxiv","authors":["Mohammed Irfan Kurpath","Jaseel Muhammad Kaithakkodan","Sahal Shaji Mullappilly","Ivan Laptev","Hisham Cholakkal"],"abstract":"Extending a text embedding model to new modalities typically degrades text retrieval quality, and existing omni-modal embedders compensate with multi-billion parameters. We present Omni-Embed-Mini, a 0.9B-parameter model that maps text, speech, audio, images, video, and visually-rich documents into a single shared cosine space without updating any text-side parameter. Our key insight is that the teacher signal requires no separate embedding model: each media sample is paired with a dense cascaded caption, and the teacher target is simply the frozen backbone's own embedding of that caption. Because teacher and student share the same backbone weights, they inhabit byte-identical geometry, and lightweight projectors plus phased LoRA adapters on the modality encoders suffice for alignment. Training combines a Matryoshka SigLIP contrastive loss with an online hybrid hard-negative miner whose "},{"hfUrl":"https://huggingface.co/papers/2610.00812","tags":["Post-Training","LLM Training","Evaluation","Alignment","Fine-tuning"],"upvotes":8,"pdf":"https://arxiv.org/pdf/2610.00812.pdf","date":"2026-10-02","submittedDate":"2026-09-30","url":"https://arxiv.org/abs/2610.00812","id":"arxiv:2610.00812","topics":["Post-Training","LLM Training","Evaluation","Alignment","Fine-tuning"],"title":"Video Generation Models: A Survey of Post-Training and Alignment","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00812","source":"arxiv","authors":["Chaoyu Li","Xiaoyi Gu","Yogesh Kulkarni","Eun Woo Im","Mohammadmahdi Honarmand","Zeyu Wang","Juntong Song","Fei Du","Xilin Jiang","Kexin Zheng","Tianzhi Li","Fei Tao","Pooyan Fazli"],"abstract":"Video generation has rapidly progressed from short, low-quality clips to high-resolution, long-duration sequences with complex spatiotemporal dynamics. Despite strong generative priors learned through large-scale pretraining, pretrained video models often fail to reliably follow human intent, maintain temporal coherence, or satisfy physical and safety constraints. Compared with image and text generation, alignment in video generation presents unique challenges, including error accumulation over time, motion-appearance coupling, multi-objective trade-offs, and limited supervision for temporal properties. These challenges motivate systematic post-training strategies that adapt pretrained models without retraining them from scratch. In this survey, we present the first comprehensive review of post-training and alignment in video generation models. We frame post-training as a unifying framew"},{"hfUrl":"https://huggingface.co/papers/2610.02117","tags":["Post-Training","Reasoning","Evaluation"],"upvotes":7,"pdf":"https://arxiv.org/pdf/2610.02117.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02117","id":"arxiv:2610.02117","topics":["Post-Training","Reasoning","Evaluation"],"title":"Where-OPD: Spatially Guided On-Policy Self-Distillation of MLLMs with Synthetic Scenes","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02117","source":"arxiv","authors":["Sophia Sirko-Galouchenko","Monika Wysoczanska","Andrei Bursuc","Nicolas Thome","Spyros Gidaris"],"abstract":"On-policy self-distillation has recently emerged as an effective approach for improving language-model reasoning by supervising students with a frozen or EMA version of themselves that receives privileged information. Its application to multimodal large language models (MLLMs), however, remains largely unexplored. Recent approaches use privileged visual information, such as image crops corresponding to a question, to improve fine-grained perception, but their gains are confined to tasks that benefit from such visual zooming and require either human-annotated grounding data or external teacher models. We introduce a different form of on-policy self-distillation for MLLMs that provides the teacher with textual, spatially grounded guidance identifying the visual elements relevant to a query. We use procedurally generated scenes with automatically available object identities and spatial coor"},{"hfUrl":"https://huggingface.co/papers/2610.01108","tags":["Multi-Agent","Code Agent","Evaluation"],"upvotes":6,"pdf":"https://arxiv.org/pdf/2610.01108.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01108","id":"arxiv:2610.01108","topics":["Multi-Agent","Code Agent","Evaluation"],"title":"AgSpec: Pushing the Limits of Retrieval-Based Speculative Decoding in Coding Agent Pipelines","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01108","source":"arxiv","authors":["Sumin Lee","Sukmin Cho","Suengjae Lim","Youngjin Kwon"],"abstract":"Retrieval-based speculative decoding (SD) drafts tokens by copying continuations from existing text, which suits coding agents that repeatedly reproduce code, logs, and earlier attempts. Yet existing methods fall short in agent pipelines: much of the reusable text is missing from their corpora or stored in a form that differs from what the agent emits, and their draft lengths ignore that accept length varies across agents and drifts over turns. We present AgSpec, a framework that supplies the corpus and draft-length policies that existing retrieval engines lack in coding-agent pipelines. AgSpec retrieves from session, workspace, and global corpora, retaining the ongoing session trajectory and indexing opened files in the agent's emission format. It bounds each agent's draft length with an offline-profiled cap and adapts the length online from verification feedback. On two repository-leve"},{"hfUrl":"https://huggingface.co/papers/2610.01428","tags":["Evaluation"],"upvotes":5,"pdf":"https://arxiv.org/pdf/2610.01428.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01428","id":"arxiv:2610.01428","topics":["Evaluation"],"title":"Generalization Is Stability, Not Accuracy: Multi-Axis Evaluation of LLMs","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01428","source":"arxiv","authors":["Nagham Omar","Mahmoud Jabarin","Maya Rozenshtein","Rom Himelstein","Avi Mendelson","Amit LeVi"],"abstract":"Generalization in large language models (LLMs) is the ability to produce consistent and semantically stable outputs when the same input is expressed in different ways. Existing work typically evaluates generalization through aggregate accuracy on a single prompt format, task, or set of variations, which conflates robustness with overall benchmark performance. In this work, we show generalization evaluation at the level of individual examples, across multiple input variants, and across different aspects of model behavior, focusing on variability rather than reducing performance to a score that can be improved through narrow training or other ways that obfuscate generalization evaluation. Following this view, we introduce the Stability-Aware Generalization Objective (SAGO), a framework that measures how much model behavior changes for the same input under different variations and benchmark"},{"hfUrl":"https://huggingface.co/papers/2610.02206","tags":["LLM Training","Tool Use","Evaluation","Fine-tuning"],"upvotes":3,"pdf":"https://arxiv.org/pdf/2610.02206.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.02206","id":"arxiv:2610.02206","topics":["LLM Training","Tool Use","Evaluation","Fine-tuning"],"title":"KaliBench: A Fine-Grained Benchmark for Cybersecurity Tool Use on Kali Linux with Runtime-Free Verifiable Rewards","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.02206","source":"arxiv","authors":["Pengfei Li","Naufal Suryanto","Sicheng Zhang","Muzammal Naseer"],"abstract":"LLMs are increasingly applied to cybersecurity workflows, where they are expected to translate analysts' intent into tool invocations. However, existing evaluations focus on knowledge-based assessments or end-to-end agentic tasks, and do not directly measure LLMs' ability to generate executable commands for real-world cybersecurity tools. This gap is critical because cybersecurity operations rely on strict command-line interfaces (CLIs), where minor syntax errors, incorrect flag--value bindings, or argument misordering can invalidate execution. We introduce KaliBench, a fine-grained benchmark and dataset for natural-language--to--CLI translation on Kali Linux, comprising 8,504 query--command pairs spanning 1,642 tools across 23 capability dimensions and 5 security phases. KaliBench is constructed via a manuscript-grounded pipeline with deterministic canonicalization and alias-aware evalu"},{"hfUrl":"https://huggingface.co/papers/2610.01499","tags":["Evaluation","Alignment","Reflection"],"upvotes":2,"pdf":"https://arxiv.org/pdf/2610.01499.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01499","id":"arxiv:2610.01499","topics":["Evaluation","Alignment","Reflection"],"title":"VTR-Bench: A Systematic Benchmark for Evaluating Visual Text Rendering in Video Generation","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01499","source":"arxiv","authors":["Yu Huang","Jungang Li","Zhiyuan Wang","Yonghua Hei","Song Dai","Jiayu Yang","Deyuan Liu","Xiang Zheng","Xiaoshuang Shi","Hao Cheng","Kaidi Xu"],"abstract":"Recent video generation models can produce highly realistic videos from natural language instructions, with visual quality approaching cinematic standards. Existing evaluation benchmarks, however, predominantly assess visual quality, aesthetic appeal and physical plausibility, while paying limited attention to text, an essential medium for conveying information in everyday scenes. A generated video may appear visually compelling and feature lifelike subjects, yet still render the text within the scene incorrectly. To address this overlooked dimension, we introduce \\textbf{VTR-Bench}, a systematic benchmark for evaluating the \\textbf{V}isual \\textbf{T}ext \\textbf{R}endering capabilities of video generation models. VTR-Bench situates text within concrete application scenarios, such as advertisements and scientific videos, with 300 carefully constructed prompts spanning five scenario catego"},{"hfUrl":"https://huggingface.co/papers/2610.00348","tags":["LLM Training","Evaluation"],"upvotes":2,"pdf":"https://arxiv.org/pdf/2610.00348.pdf","date":"2026-10-02","submittedDate":"2026-09-29","url":"https://arxiv.org/abs/2610.00348","id":"arxiv:2610.00348","topics":["LLM Training","Evaluation"],"title":"Removing the NEEDLE in the Haystack: Backdoor Removal in LLMs via Weight Orthogonalisation","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00348","source":"arxiv","authors":["Minoo Kim","Vasileios Lampos","George Drayson"],"abstract":"Backdoor attacks can be implanted in Large Language Models (LLMs) during training, causing unwanted behaviour when a trigger appears in the input. Existing backdoor defences for LLMs attempt to remove the backdoor but inadvertently shift the model's output distribution to benign prompts, which can result in degraded model performance and safety. We propose NEEDLE, a training-free method for targeted backdoor removal. Once a trigger has been identified, our method estimates a backdoor direction and a refusal subspace through activation vectors, then applies sequential weight orthogonalisation to suppress the backdoor while preventing changes in refusal-related representations. NEEDLE requires neither a clean reference model nor the original poisoned training data. Evaluation is conducted across multiple model families and attack types. NEEDLE achieves the lowest mean Attack Success Rate ("},{"tags":["Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.01892.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01892","id":"arxiv:2610.01892","topics":["Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning","Multimodal Agent","RL for LLM"],"title":"Selection-Based Structured Reasoning: Toward Efficient Multimodal Search Agents","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01892","source":"arxiv","authors":["Feiyu Gavin Zhu","Xiaoyu Zhu","Jiqi Yang","Rui Yang","Arnab Kumar Mondal","Yancheng Wang","Xinke Deng","Jean Oh","Reid Simmons","Joerg Liebelt","Xiang Kong","Zhongyu Jiang"],"abstract":"Multimodal agents commonly generate free-form reasoning before each action. For small models, limited model capacity can result in lengthy reasoning that provides little useful guidance for action generation while incurring substantial inference cost. To address this challenge, we introduce Selection-based Structured Reasoning (SSR), a framework that reformulates reasoning as selection instead of open-ended generation. SSR represents recurring high-level reasoning as pre-specified, reusable natural-language candidates. At each turn, the model selects from these reasoning candidates based on their likelihoods given the current context, without requiring an auxiliary task head. Using pre-specified reasoning traces enables parallel scoring, where teacher-forced prefilling computes token likelihoods concurrently within and across candidates using a shared context KV cache. We evaluate SSR on"},{"tags":["Post-Training","LLM Training","VLM Training","Tool Use","Reasoning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.01166.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01166","id":"arxiv:2610.01166","topics":["Post-Training","LLM Training","VLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning"],"title":"CineMR: Tool-Integrated Vision-Language Reasoning for Quantitative Cardiac MRI Assessment","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01166","source":"arxiv","authors":["Kunyang Li","Hai Nguyen","Joshua Lowe","Chenguang Zhao","Peace C. Madueme","Mehdi Hedjazi Moghari","Mubarak Shah","Pegah Khosravi","Yuzhang Zhang"],"abstract":"Cardiovascular magnetic resonance (CMR), including cine imaging, is a reference standard for the noninvasive assessment of cardiac morphology and ventricular function. Cine CMR interpretation integrates qualitative visual assessment with quantitative measurements of ventricular volumes, ejection fraction, myocardial mass, wall thickness, and regional wall motion. Current medical vision-language models (VLMs) cannot reliably derive quantitative measurements from multidimensional cine images without analysis tools. We present CineMR, a tool-augmented VLM that invokes cardiac image-analysis tools and integrates their outputs into interleaved reasoning for quantitative CMR assessment. We also construct a multi-cohort visual question answering benchmark covering quantitative metric extraction, multiclass diagnosis, and differential diagnosis, together with tools for segmentation, phase select"},{"tags":["Post-Training","LLM Training","VLM Training","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.01800.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01800","id":"arxiv:2610.01800","topics":["Post-Training","LLM Training","VLM Training","Evaluation","Fine-tuning","RL for LLM"],"title":"LineupRL: Verifiable Reinforcement Learning for Time Series Captioning via Caption-to-Series Identification","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01800","source":"arxiv","authors":["Haochen Zhang","Laura Yao","Zachary Plotkin","Gengwei Zhang","Tianlong Chen"],"abstract":"Time series captioning is a fundamental step in time series understanding and can also serve as the bridge between signal and natural language. Supervised fine-tuning (SFT) relies on a larger model's captions and cannot exceed their quality. Reinforcement learning (RL) can, but its rewards were designed for other modalities and other tasks, and they transfer poorly to open-ended generation in the time series domain. We address this by proposing LineupRL, a reinforcement learning with verifiable rewards (RLVR) pipeline whose reward is caption-to-series identification. The reward model is a frozen large language model (LLM) verifier that reads the generated caption and the candidate time series as raw values, never the chart, and must pick the described time series from multiple distractors. Matching is a far lighter demand on the verifier than writing questions or judging a caption, so an"},{"tags":["Post-Training","LLM Training","Reasoning","Hallucination","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.00568.pdf","date":"2026-10-02","submittedDate":"2026-09-30","url":"https://arxiv.org/abs/2610.00568","id":"arxiv:2610.00568","topics":["Post-Training","LLM Training","Reasoning","Hallucination","Evaluation","Alignment"],"title":"Emergent Unfaithfulness: How Alignment Training Causes Language Models to Silently Override Task Faithfulness","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00568","source":"arxiv","authors":["Pardis Sadat Zahraei","Janvijay Singh","Gokhan Tur","Dilek Hakkani-Tur"],"abstract":"Large language models are characterized by three key properties: capability, alignment, and faithfulness. Prior work studies the tradeoffs between capability and alignment, and between capability and faithfulness, but a third tension remains underexplored: the alignment-faithfulness conflict. We show that aligned models systematically deviate from their inputs on unsafe or sensitive content without disclosing the modification, a failure mode we call alignment-induced unfaithfulness (AIU). Unlike capability-driven unfaithfulness, which comes from errors in knowledge or reasoning, this is induced by post-training mechanisms that override adherence to the input. We introduce FaithConflict, a controlled dataset isolating both conflicts, and two complementary taxonomies: behavioral (B1-B8) and chain-of-thought reasoning (C0-C6). Across models, AIU increases with scale and more sharply than ca"},{"tags":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.00406.pdf","date":"2026-10-02","submittedDate":"2026-09-30","url":"https://arxiv.org/abs/2610.00406","id":"arxiv:2610.00406","topics":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation","Alignment"],"title":"LLM-as-a-Judge for Low-Resource Languages: Adapting Ragas and Comparative Ranking for Romanian","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00406","source":"arxiv","authors":["Claudiu Creanga","Liviu P. Dinu"],"abstract":"Evaluating Retrieval-Augmented Generation (RAG) systems remains a challenge for Low-Resource Languages (LRLs), where standard reference-based metrics fall short. This paper investigates the viability of the \"LLM-as-a-Judge\" paradigm for Romanian by adapting the Ragas framework using next-generation models (Gemini 2.5 and Gemini 3). We introduce AdminRo-Eval, a curated dataset of Romanian administrative documents annotated by native speakers, to serve as a ground truth for benchmarking automated evaluators. We compare three evaluation methodologies - direct scoring, comparative ranking, and granular decomposition - across metrics for Faithfulness, Answer Relevance, and Context Relevance. Our findings reveal that evaluation strategies must be metric-specific: granular decomposition achieves the highest human alignment for Faithfulness (96% with Gemini 2.5 Pro), while comparative ranking ou"},{"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.01729.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01729","id":"arxiv:2610.01729","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"title":"Function-Structured Reinforcement Learning with Executable Verifiers for Mathematical Reasoning","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01729","source":"arxiv","authors":["Zihan Liu","Xurong Xie"],"abstract":"Algorithmic mathematical reasoning requires reliable decomposition, computation, and aggregation. Final-answer rewards provide limited guidance on intermediate errors, while successful execution does not guarantee mathematical correctness. This work proposes Function-Structured Graph Reinforcement Learning (FSG-RL), connecting subproblem graphs and Python implementations with multi-verifier feedback. The policy first learns to generate code from function graphs through supervised fine-tuning (SFT). Group Relative Policy Optimization (GRPO) then optimizes the policy using answer-gated rewards and span-level credit assignment. The framework also supports teacher supervision and structured memory. A benchmark curated from Grade School Math 8K (GSM8K), MathQA, MATH, and Omni-MATH pairs public function graphs with private verification specifications. Under a unified evaluation protocol, GRPO "},{"tags":["LLM Training","Reasoning","Code Agent","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.00949.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.00949","id":"arxiv:2610.00949","topics":["LLM Training","Reasoning","Code Agent","Evaluation","Fine-tuning"],"title":"PG-SFT: Balancing Capability Acquisition and Retention in Offline Agent Fine-Tuning","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.00949","source":"arxiv","authors":["Ronghua Li","Zi Liang","Zhishan Li","Shinan Liu"],"abstract":"Supervised fine-tuning (SFT) on offline agent trajectories is the standard approach for training specialized tool-using agents, but forcing models to imitate reasoning and actions token by token may harm other capabilities (e.g., general reasoning, tool calling, code generation) of the base model. In this work, we focus on studying \\emph{how to better balance the trade-off between acquiring new capabilities and preserving existing ones during agent trace SFT}. By comparing several baselines in our setup, standard SFT improves the target benchmark while lowering several non-target benchmark scores; meanwhile, simply constraining distributional drift using KL penalty or limiting the update magnitude did not avoid this regression trend. Motivated by recent token-wise adaptive learning objectives, this work proposes \\textbf{Privilege-Guided SFT (PG-SFT)} to leverage turn-level information ga"},{"tags":["VLM Training","Reasoning","Evaluation","Alignment","Reflection"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2610.01383.pdf","date":"2026-10-02","submittedDate":"2026-10-01","url":"https://arxiv.org/abs/2610.01383","id":"arxiv:2610.01383","topics":["VLM Training","Reasoning","Evaluation","Alignment","Reflection"],"title":"PRISM: A Category-Theoretic Framework for Measuring and Refining Multimodal Analogies","announceDate":"2026-10-02","arxiv":"https://arxiv.org/abs/2610.01383","source":"arxiv","authors":["Mirella Zeisler","Ojas Shirekar","Mircea Licǎ","Chirag Raman"],"abstract":"Analogical reasoning involves identifying and preserving relational structures across domains. However, existing approaches to AI-driven multimodal analogy generation lack an interpretable measure of whether this structure is understood and maintained in the generated output. We address this gap with Pullback Refinement via Interpretable Structural Mapping (PRISM), a modality-agnostic framework for measuring and improving relational alignment in multimodal analogies, evaluated on visual metaphor generation. PRISM represents analogies as explicit relational mappings grounded in category theory and uses VLMs to instantiate these structures across modalities. Its first component, the pullback score, quantifies relational alignment from the resulting graph representation. On the AnaloBench benchmark, selecting the correct analogy purely by pullback score achieves 82.5% accuracy, demonstratin"}],"archive":[],"latestPath":"data/latest.json"};
